import{_ as t,o,c as a,ak as n}from"./chunks/framework.B8jO0odJ.js";const m=JSON.parse('{"title":"Chainy role ownership","description":"Historical snapshot taken before v2 adoption on October 23, 2026. Not active requirements or current progress. See the adoption archive.","frontmatter":{"title":"Chainy role ownership","description":"Historical snapshot taken before v2 adoption on October 23, 2026. Not active requirements or current progress. See the adoption archive.","source":"docs/archive/pre-v2-adoption-2026-10-23/docs/team-delegation.md","category":"Archive","sourceUpdated":"2026-10-23T16:51:22+08:00","outline":[2,3]},"headers":[],"relativePath":"content/docs/archive/pre-v2-adoption-2026-10-23/docs/team-delegation.md","filePath":"content/docs/archive/pre-v2-adoption-2026-10-23/docs/team-delegation.md"}'),r={name:"content/docs/archive/pre-v2-adoption-2026-10-23/docs/team-delegation.md"};function i(s,e,d,c,h,l){return o(),a("div",null,[...e[0]||(e[0]=[n('<div><h1 id="chainy-role-ownership">Chainy role ownership<a class="header-anchor" href="#chainy-role-ownership" aria-label="Link to this section">​</a></h1><blockquote><p>Historical snapshot taken before v2 adoption on October 23, 2026. Not active requirements or current progress. See the <a href="/Chainy-Docs/content/docs/archive/pre-v2-adoption-2026-10-23/readme.html">adoption archive</a>.</p></blockquote><p>Updated October 13, 2026. <strong>Beta: November 3–6, 2026. Pre-final: November 21, 2026. Both dates are fixed.</strong></p><p>Every active board card has one person responsible for one kind of work. Do not add helpers or reviewers to a card. If the next step belongs to a different role, create a separate card for that handoff. Team-board edit access is shared; task ownership is not.</p><table><thead><tr><th>Person and role</th><th>Owns</th><th>Does not own</th></tr></thead><tbody><tr><td><strong>Sherwin Limosnero — Project and Design Lead</strong></td><td>Schedule and scope decisions; school coordination; learner experience and decisions about how each mode works.</td><td>Game code, final authored documentation, art production, or screen implementation.</td></tr><tr><td><strong>Christian Jude Villaber — Tech Lead</strong></td><td>Unity/game code, SQLite implementation, technical behavior, Android builds, technical integration, and technical checks.</td><td>Art production, authored project documentation, or game-screen visual implementation.</td></tr><tr><td><strong>Luis Cabrido III — Art Lead</strong></td><td>Art direction and creation/export of game art assets.</td><td>Game UI implementation, game code, or manuscript/guide writing.</td></tr><tr><td><strong>Sean Matthew Narvaez — Docs Lead</strong></td><td>Writing and maintaining all project documents, guides, instructions, test forms, and evidence reports.</td><td>Making design decisions, coding, or making game artwork.</td></tr><tr><td><strong>Miguel De Leon — UI support</strong></td><td>Implementing and adjusting player-facing game screens and UI assets supplied through the art handoff.</td><td>Writing project documentation, deciding game rules, making general game art, or owning game logic.</td></tr></tbody></table><p>The interactive board and Gantt chart are the task/status source of truth. The board gives each person an individual login and records who changed a card, what changed, where it changed, and when. A card owner name does not imply that the person has a GitHub account. The GitHub issue is a linked execution copy.</p><h2 id="how-work-passes-between-roles">How work passes between roles<a class="header-anchor" href="#how-work-passes-between-roles" aria-label="Link to this section">​</a></h2><ol><li>The owner creates the output named on their card and records the link or evidence there.</li><li>When another role must act, the owner marks the handoff ready and names the next card in the dependency.</li><li>The next owner checks the handoff and records their own work on their own card.</li><li>Christian owns game-code integration. Sean owns written reporting. Each owner checks only the acceptance conditions for their lane.</li><li>If an input is missing, keep the card visible and describe the blocker. Do not move it to Done or hide the dependency.</li></ol><h2 id="parallel-work-boundaries">Parallel-work boundaries<a class="header-anchor" href="#parallel-work-boundaries" aria-label="Link to this section">​</a></h2><p>Cards in different role lanes can run together only when neither uses another lane&#39;s unfinished output. Cards that edit the same game files run one at a time under Christian&#39;s integration plan. Game-source work must wait until the Tech Lead records the exact game repository revision, Unity version, build steps, and available Android build. The external game repository is <a href="https://github.com/Kamiyon-Studio/Chainy-Game">Kamiyon-Studio/Chainy-Game</a>; this management repository does not prove that the game source has been checked out.</p><p>Use the <a href="/Chainy-Docs/content/docs/archive/pre-v2-adoption-2026-10-23/docs/kanban-plan-draft.html">task plan</a> for the role-owned work packets and dependencies, the <a href="/Chainy-Docs/content/docs/team-board-guide.html">team board guide</a> for card updates, and the <a href="/Chainy-Docs/content/docs/archive/pre-v2-adoption-2026-10-23/docs/project-baseline.html">baseline</a> for approved decisions. Documentation authorship belongs to Sean; technical facts require Christian&#39;s input, and design choices remain Sherwin&#39;s decisions.</p></div>',1)])])}const u=t(r,[["render",i]]);export{m as __pageData,u as default};
